#include <stdio.h>

int main() {
    int a[] = {5, 2, 7, 1, 3};
    int prefix[6] = {0};
    for (int i = 0; i < 5; i++) {
        prefix[i + 1] = prefix[i] + a[i];
    }
    int queries[3][2] = {{0, 2}, {1, 4}, {2, 3}};
    for (int k = 0; k < 3; k++) {
        printf("%d\n", prefix[queries[k][1] + 1] - prefix[queries[k][0]]);
    }
    return 0;
}
